package main

import (
    "fmt"
    "html"
    "log"
    "net/http"
    "time"
)

// HandleProductSearch displays search results with analytics support.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    keyword := r.URL.Query().Get("keyword")

    // Analytics logging: record search event with keyword, remote address, user agent, and timestamp.
    log.Printf("SEARCH_ANALYTICS keyword=%q remote_addr=%s user_agent=%q timestamp=%s",
        keyword,
        r.RemoteAddr,
        r.UserAgent(),
        time.Now().UTC().Format(time.RFC3339),
    )

    // Set response content type to HTML.
    w.Header().Set("Content-Type", "text/html; charset=utf-8")

    // Render the search keyword safely using HTML escaping to prevent XSS.
    fmt.Fprintf(w, `<h2>Search Results: %s</h2>`, html.EscapeString(keyword))
}

func main() {
    http.HandleFunc("/search", HandleProductSearch)

    log.Println("Product search server listening on :8080")
    log.Fatal(http.ListenAndServe(":8080", nil))
}

