package main

import (
    "fmt"
    "html"
    "log"
    "net/http"
    "os"
)

// HandleProductSearch handles the search results page.
// It reads the "keyword" query parameter, displays it safely,
// and logs it for analytics.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    // Extract the keyword from the query string
    keyword := r.URL.Query().Get("keyword")

    // Escape HTML to prevent XSS
    safeKeyword := html.EscapeString(keyword)

    // Analytics: log the search keyword server‑side
    log.Printf("Search keyword: %s\n", keyword)

    // Set Content-Type header
    w.Header().Set("Content-Type", "text/html; charset=utf-8")

    // Write a complete HTML document with the required <h2> heading
    fmt.Fprintf(w, `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>Search Results: %s</title>
</head>
<body>
    <h2>Search Results: %s</h2>
    <p>Displaying results for "%s".</p>
</body>
</html>`, safeKeyword, safeKeyword, safeKeyword)
}

func main() {
    // Register the handler on the /search endpoint
    http.HandleFunc("/search", HandleProductSearch)

    // Determine port from environment or default to 8080
    port := os.Getenv("PORT")
    if port == "" {
        port = "8080"
    }

    log.Printf("Server starting on :%s\n", port)
    if err := http.ListenAndServe(":"+port, nil); err != nil {
        log.Fatalf("server failed: %v", err)
    }
}

