package main

import (
	"html"
	"log"
	"net/http"
	"net/url"
)

func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	keyword := r.URL.Query().Get("keyword")

	// Escape to prevent XSS
	escapedKeyword := html.EscapeString(keyword)

	// Set Content-Type
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Build the response
	htmlResponse := `<!DOCTYPE html>
<html>
<head>
<title>Product Search Results</title>
</head>
<body>
<h2>Search Results: ` + escapedKeyword + `</h2>
</body>
</html>`

	w.Write([]byte(htmlResponse))

	// Analytics tracking (non-blocking)
	go trackSearch(keyword)
}

// trackSearch sends the search keyword to an analytics endpoint.
func trackSearch(keyword string) {
	resp, err := http.PostForm("http://localhost:9090/analytics/search",
		url.Values{"keyword": {keyword}})
	if err != nil {
		log.Printf("analytics error: %v", err)
		return
	}
	defer resp.Body.Close()
}

