package main

import (
    "html"
    "log"
    "net/http"
    "time"
)

// HandleProductSearch handles the product search results page.
// It reads the "keyword" query parameter, logs the search for analytics,
// and responds with an HTML page displaying the search term.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    // Extract the search keyword from the URL query string
    keyword := r.URL.Query().Get("keyword")

    // Simple analytics: log the keyword and timestamp (could be sent to a data store)
    log.Printf("analytics: search keyword '%s' at %s", keyword, time.Now().Format(time.RFC3339))

    // Set the response content type to HTML
    w.Header().Set("Content-Type", "text/html; charset=utf-8")

    // Escape the keyword to prevent XSS attacks
    escapedKeyword := html.EscapeString(keyword)

    // Build the HTML page
    htmlPage := `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results</title>
</head>
<body>
    <h2>Search Results: ` + escapedKeyword + `</h2>
</body>
</html>`

    // Write the response
    w.Write([]byte(htmlPage))
}

func main() {
    // Register the handler on the "/search" endpoint
    http.HandleFunc("/search", HandleProductSearch)

    log.Println("Server listening on :8080")
    log.Fatal(http.ListenAndServe(":8080", nil))
}

