// HandleProductSearch handles the product search results page.
// It extracts the "keyword" query parameter, displays it in an <h2> tag,
// and triggers an analytics event.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    keyword := r.URL.Query().Get("keyword")

    // Trigger analytics logging (non-blocking)
    go logAnalytics(keyword)

    // Set the content type to HTML
    w.Header().Set("Content-Type", "text/html; charset=utf-8")

    // Escape the keyword to prevent XSS
    escapedKeyword := html.EscapeString(keyword)

    // Build the HTML response
    htmlContent := `<!DOCTYPE html>
<html>
<head>
    <title>Search Results</title>
</head>
<body>
    <h2>Search Results: ` + escapedKeyword + `</h2>
    <p>Showing results for: ` + escapedKeyword + `</p>
    <!-- Additional product listing would go here -->
</body>
</html>`

    fmt.Fprint(w, htmlContent)
}

// logAnalytics logs the search event to standard output (simulating an analytics service).
// In a real implementation, this would send data to an analytics endpoint.
func logAnalytics(keyword string) {
    fmt.Printf("[%s] ANALYTICS: search event, keyword='%s'\n",
        time.Now().Format(time.RFC3339), keyword)
}

func main() {
    http.HandleFunc("/search", HandleProductSearch)
    fmt.Println("Server starting on :8080")
    if err := http.ListenAndServe(":8080", nil); err != nil {
        fmt.Printf("Server failed: %s\n", err)
    }
}

