package main

import (
    "html/template"
    "log"
    "net/http"
)

// HandleProductSearch handles the product search results page.
// It reads the "keyword" query parameter, displays it, and logs analytics.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    // Extract keyword from URL query parameters.
    keyword := r.URL.Query().Get("keyword")

    // --- Analytics support ---
    // Log the search event with timestamp, keyword, and user agent.
    log.Printf("SEARCH_ANALYTICS keyword=%q user_agent=%q", keyword, r.UserAgent())

    // Prepare HTML template with proper escaping.
    const tpl = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Product Search Results</title>
</head>
<body>
    <h2>Search Results: {{.Keyword}}</h2>
    {{if .Keyword}}
        <p>Showing products matching "{{.Keyword}}".</p>
    {{else}}
        <p>No search keyword provided. Please enter a keyword to search.</p>
    {{end}}
</body>
</html>`

    tmpl, err := template.New("search").Parse(tpl)
    if err != nil {
        log.Printf("ERROR parsing template: %v", err)
        http.Error(w, "Internal Server Error", http.StatusInternalServerError)
        return
    }

    // Set response content type to HTML.
    w.Header().Set("Content-Type", "text/html; charset=utf-8")
    w.WriteHeader(http.StatusOK)

    data := struct {
        Keyword string
    }{
        Keyword: keyword,
    }

    if err := tmpl.Execute(w, data); err != nil {
        log.Printf("ERROR executing template: %v", err)
    }
}

func main() {
    // Register the handler for the /search endpoint.
    http.HandleFunc("/search", HandleProductSearch)

    log.Println("Product search server listening on :8080")
    if err := http.ListenAndServe(":8080", nil); err != nil {
        log.Fatalf("Server failed to start: %v", err)
    }
}

