package main

import (
	"fmt"
	"log"
	"net/http"
	"time"
)

// HandleProductSearch handles the product search page.
// It extracts the "keyword" query parameter and renders an HTML response
// with analytics support (keyword is logged on the server).
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract the search keyword from the URL query string
	keyword := r.URL.Query().Get("keyword")

	// Analytics support: log the search event with timestamp
	log.Printf("ANALYTICS: search keyword=%s at %s", keyword, time.Now().Format(time.RFC3339))

	// Set response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Write the HTML response
	fmt.Fprintf(w, `<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Search Results: %s</title>
</head>
<body>
    <h2>Search Results: %s</h2>
    <p>Displaying results for the keyword you entered.</p>
</body>
</html>`, keyword, keyword)
}

func main() {
	// Register the handler for the /search endpoint
	http.HandleFunc("/search", HandleProductSearch)

	fmt.Println("Server listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

