package main

import (
    "fmt"
    "html"
    "log"
    "net/http"
    "strings"
    "time"
)

// Product represents a simple product in our catalog.
type Product struct {
    Name string
}

var products = []Product{
    {Name: "Go Programming Book"},
    {Name: "Gopher Plush Toy"},
    {Name: "Standard Library Mug"},
    {Name: "Concurrency T-Shirt"},
}

// HandleProductSearch handles product search requests and displays results.
// It reads the "keyword" query parameter, logs the search event (analytics),
// filters the product list, and renders an HTML results page.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    keyword := r.URL.Query().Get("keyword")

    // Analytics support: log the search event with metadata.
    logSearchEvent(r, keyword)

    w.Header().Set("Content-Type", "text/html; charset=utf-8")
    fmt.Fprintf(w, "<!DOCTYPE html><html><head><title>Search Results</title></head><body>")
    fmt.Fprintf(w, "<h2>Search Results: %s</h2>", html.EscapeString(keyword))

    if keyword == "" {
        fmt.Fprintf(w, "<p>Please enter a search keyword.</p>")
    } else {
        filtered := filterProducts(keyword)
        if len(filtered) == 0 {
            fmt.Fprintf(w, "<p>No products found matching your query.</p>")
        } else {
            fmt.Fprintf(w, "<ul>")
            for _, p := range filtered {
                fmt.Fprintf(w, "<li>%s</li>", html.EscapeString(p.Name))
            }
            fmt.Fprintf(w, "</ul>")
        }
    }
    fmt.Fprintf(w, "</body></html>")
}

// filterProducts returns products whose name contains the given keyword (case-insensitive).
func filterProducts(keyword string) []Product {
    lowerKeyword := strings.ToLower(keyword)
    var result []Product
    for _, p := range products {
        if strings.Contains(strings.ToLower(p.Name), lowerKeyword) {
            result = append(result, p)
        }
    }
    return result
}

// logSearchEvent records search queries for analytics purposes.
// For demonstration, we log to standard output; production could write to a file or external service.
func logSearchEvent(r *http.Request, keyword string) {
    log.Printf("[ANALYTICS] Search keyword=%q | IP=%s | User-Agent=%s | Time=%s",
        keyword,
        r.RemoteAddr,
        r.UserAgent(),
        time.Now().Format(time.RFC3339),
    )
}

func main() {
    http.HandleFunc("/search", HandleProductSearch)
    log.Println("Product search server starting on :8080")
    log.Fatal(http.ListenAndServe(":8080", nil))
}

