package main

import (
    "fmt"
    "html"
    "log"
    "net/http"
    "time"
)

// HandleProductSearch handles product search requests and displays the keyword with analytics.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
    // Set the response content type to HTML
    w.Header().Set("Content-Type", "text/html; charset=utf-8")

    // Extract the search keyword from the URL query parameter
    keyword := r.URL.Query().Get("keyword")

    // Analytics support: log the search event with timestamp and client IP
    log.Printf("Search query: %q from %s at %s", keyword, r.RemoteAddr, time.Now().Format(time.RFC3339))

    // Escape the keyword to prevent XSS attacks
    escapedKeyword := html.EscapeString(keyword)

    // Build the HTML response with the search results title
    htmlResponse := fmt.Sprintf(`<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results</title>
</head>
<body>
    <h2>Search Results: %s</h2>
</body>
</html>`, escapedKeyword)

    // Write the HTML response
    fmt.Fprint(w, htmlResponse)
}

func main() {
    // Register the handler for the /search endpoint
    http.HandleFunc("/search", HandleProductSearch)

    // Start the HTTP server
    fmt.Println("Server starting on :8080")
    log.Fatal(http.ListenAndServe(":8080", nil))
}

