import (
	"fmt"
	"html"
	"log"
	"net/http"
	"sync"
	"time"
)

type SearchRecord struct {
	Keyword string
	Time    time.Time
}

var (
	mu         sync.Mutex
	searchLogs []SearchRecord
)

// HandleProductSearch handles product search results and records analytics.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	keyword := r.URL.Query().Get("keyword")

	// Analytics: record search asynchronously
	go func() {
		mu.Lock()
		searchLogs = append(searchLogs, SearchRecord{Keyword: keyword, Time: time.Now()})
		mu.Unlock()
		log.Printf("Search analytics: keyword=%q, time=%v\n", keyword, time.Now())
	}()

	// Sanitize keyword for safe HTML output
	safeKeyword := html.EscapeString(keyword)
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Build the HTML response
	fmt.Fprintf(w, "<!DOCTYPE html><html><head><title>Search Results: %s</title></head><body>", safeKeyword)
	fmt.Fprintf(w, "<h2>Search Results: %s</h2>", safeKeyword)

	if keyword == "" {
		fmt.Fprint(w, "<p>No keyword provided.</p>")
	} else {
		fmt.Fprintf(w, "<p>Showing results for: %s</p>", safeKeyword)
		fmt.Fprint(w, "<ul><li>Product A</li><li>Product B</li></ul>")
	}
	fmt.Fprint(w, "</body></html>")
}

func main() {
	http.HandleFunc("/search", HandleProductSearch)
	log.Println("Server starting on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

