package main

import (
	"fmt"
	"html"
	"log"
	"net/http"
	"sync"
	"time"
)

// Analytics stores keyword search counts (in-memory analytics).
type Analytics struct {
	mu     sync.Mutex
	counts map[string]int
}

// Record increments the search count for the given keyword.
func (a *Analytics) Record(keyword string) {
	a.mu.Lock()
	a.counts[keyword]++
	a.mu.Unlock()
}

// analytics instance (package‑level).
var analytics = &Analytics{counts: make(map[string]int)}

// HandleProductSearch serves the product search results page.
// It reads the "keyword" query parameter, displays it in an <h2>,
// and records the search for analytics purposes.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract the keyword from the URL query string.
	keyword := r.URL.Query().Get("keyword")

	// Analytics: log the search request with a timestamp.
	log.Printf("Analytics: search keyword=%q at %s",
		keyword, time.Now().Format(time.RFC3339))

	// Analytics: record the keyword in our in-memory counter.
	analytics.Record(keyword)

	// Set the response content type to HTML.
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Write the HTML page with the search results header.
	// html.EscapeString prevents XSS when displaying user input.
	fmt.Fprintf(w, `<html>
	<body>
		<h2>Search Results: %s</h2>
	</body>
</html>`, html.EscapeString(keyword))
}

func main() {
	// Register the handler.
	http.HandleFunc("/search", HandleProductSearch)

	// (Optional) serve a simple analytics dashboard.
	http.HandleFunc("/analytics", func(w http.ResponseWriter, r *http.Request) {
		analytics.mu.Lock()
		data := analytics.counts // shallow copy is fine for a quick dashboard
		analytics.mu.Unlock()

		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		fmt.Fprintln(w, "Keyword search counts:")
		for kw, cnt := range data {
			fmt.Fprintf(w, "  %s: %d\n", kw, cnt)
		}
	})

	// Start the HTTP server.
	log.Println("Server listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

